17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.Collections;
22	import java.util.List;
23	import java.util.Locale;
24	import java.util.Map;
25	import java.util.Objects;
26	import java.util.stream.Collectors;
27	
28	import org.springframework.http.HttpHeaders;
29	import org.springframework.http.HttpStatus;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.mapper.OwnerMapper;
32	import org.springframework.samples.petclinic.mapper.PetMapper;
33	import org.springframework.samples.petclinic.mapper.VisitMapper;
34	import org.springframework.samples.petclinic.model.Owner;
35	import org.springframework.samples.petclinic.model.Pet;
36	import org.springframework.samples.petclinic.model.Visit;
37	import org.springframework.samples.petclinic.rest.api.OwnersApi;
38	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
39	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.PetDto;
41	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    private final ClinicService clinicService;
63	
64	    private final OwnerMapper ownerMapper;
65	
66	    private final PetMapper petMapper;
67	
68	    private final VisitMapper visitMapper;
69	
70	    public OwnerRestControllerV1(ClinicService clinicService,
71	                                 OwnerMapper ownerMapper,
72	                                 PetMapper petMapper,
73	                                 VisitMapper visitMapper) {
74	        this.clinicService = clinicService;
75	        this.ownerMapper = ownerMapper;
76	        this.petMapper = petMapper;
77	        this.visitMapper = visitMapper;
78	    }
79	
80	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
81	    @Override
82	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
83	        Collection<Owner> owners;
84	        if (lastName != null) {
85	            owners = this.clinicService.findOwnerByLastName(lastName);
86	        } else {
87	            owners = this.clinicService.findAllOwners();
88	        }
89	        if (owners.isEmpty()) {
90	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
91	        }
92	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
93	    }
94	
95	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
96	    @Override
97	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
98	        Owner owner = this.clinicService.findOwnerById(ownerId);
99	        if (owner == null) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
108	        HttpHeaders headers = new HttpHeaders();
109	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
110	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
111	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
112	            return new ResponseEntity<>(HttpStatus.CONFLICT);
113	        }
114	        if (owner.getRegistrationDate() == null) {
115	            owner.setRegistrationDate(LocalDate.now());
116	        }
117	        if (hasReachedDailyRegistrationLimit(owner.getRegistrationDate())) {
118	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
119	        }
120	        if (hasReachedCityCapacity(owner.getCity())) {
121	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
122	        }
123	        owner.setNamesakeCount(countNamesakes(owner.getLastName()));
124	        owner.setSharesHousehold(sharesHousehold(owner));
125	        owner.setLocality(determineLocality(owner.getCity()));
126	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
127	        owner.setMembershipTier(determineMembershipTier(owner.getMembershipNumber()));
128	        owner.setCity(normalizeCity(owner.getCity()));
129	        owner.setCustomerCode(generateCustomerCode(owner.getCity()));
130	        this.clinicService.saveOwner(owner);
131	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
132	        headers.setLocation(UriComponentsBuilder.newInstance()
133	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
134	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
135	    }
136	
137	    /**
138	     * The maximum number of owners that may be registered on any single day.
139	     */
140	    private static final long MAX_OWNERS_PER_DAY = 20;
141	
142	    /**
143	     * Determines whether the number of owners already registered on the given date has reached the
144	     * daily registration limit. When 20 owners share the same registration date, no further owner may
145	     * be created for that day.
146	     */
147	    private boolean hasReachedDailyRegistrationLimit(LocalDate registrationDate) {
148	        long ownersRegisteredOnDate = this.clinicService.findAllOwners().stream()
149	            .filter(existing -> Objects.equals(existing.getRegistrationDate(), registrationDate))
150	            .count();
151	        return ownersRegisteredOnDate >= MAX_OWNERS_PER_DAY;
152	    }
153	
154	    /**
155	     * The maximum number of owners that may share a single city.
156	     */
157	    private static final long MAX_OWNERS_PER_CITY = 8;
158	
159	    /**
160	     * Determines whether the given city has already reached its capacity of owners. When a city
161	     * already contains 8 owners, no further owner may be created in that city. Cities are matched
162	     * ignoring letter case.
163	     */
164	    private boolean hasReachedCityCapacity(String city) {
165	        if (city == null) {
166	            return false;
167	        }
168	        long ownersInCity = this.clinicService.findAllOwners().stream()
169	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
170	            .count();
171	        return ownersInCity >= MAX_OWNERS_PER_CITY;
172	    }
173	
174	    /**
175	     * Counts how many existing owners share the given last name at the moment a new owner is
176	     * created. The newly created owner itself is not yet persisted and so is never included in
177	     * the count. Last names are compared exactly.
178	     */
179	    private int countNamesakes(String lastName) {
180	        if (lastName == null) {
181	            return 0;
182	        }
183	        return (int) this.clinicService.findAllOwners().stream()
184	            .filter(existing -> Objects.equals(existing.getLastName(), lastName))
185	            .count();
186	    }
187	
188	    /**
189	     * Determines whether the given owner shares a household with an owner that already exists,
190	     * meaning another owner already has the same address and city. Addresses and cities are
191	     * compared ignoring letter case and any surrounding or repeated whitespace. The newly created
192	     * owner itself is not yet persisted and so is never matched against.
193	     */
194	    private boolean sharesHousehold(Owner owner) {
195	        String address = normalize(owner.getAddress());
196	        String city = normalize(owner.getCity());
197	        if (address == null || city == null) {
198	            return false;
199	        }
200	        return this.clinicService.findAllOwners().stream()
201	            .anyMatch(existing -> Objects.equals(normalize(existing.getAddress()), address)
202	                && Objects.equals(normalize(existing.getCity()), city));
203	    }
204	
205	    /**
206	     * Determines the locality of a newly created owner based on its city. The owner is 'local'
207	     * when its city is the single most common city among the owners that already exist at the
208	     * moment of creation; otherwise it is 'remote'. When no city is the sole most common one
209	     * (for example because two cities are tied for the highest count, or no owners yet exist),
210	     * every newly created owner is 'remote'. Cities are compared ignoring letter case.
211	     */
212	    private String determineLocality(String city) {
213	        if (city == null) {
214	            return "REMOTE";
215	        }
216	        Map<String, Long> cityCounts = this.clinicService.findAllOwners().stream()
217	            .map(Owner::getCity)
218	            .filter(existing -> existing != null)
219	            .collect(Collectors.groupingBy(existing -> existing.toLowerCase(Locale.ROOT), Collectors.counting()));
220	        if (cityCounts.isEmpty()) {
221	            return "REMOTE";
222	        }
223	        long maxCount = Collections.max(cityCounts.values());
224	        List<String> mostCommonCities = cityCounts.entrySet().stream()
225	            .filter(entry -> entry.getValue() == maxCount)
226	            .map(Map.Entry::getKey)
227	            .toList();
228	        if (mostCommonCities.size() != 1) {
229	            return "REMOTE";
230	        }
231	        return mostCommonCities.get(0).equals(city.toLowerCase(Locale.ROOT)) ? "LOCAL" : "REMOTE";
232	    }
233	
234	    /**
235	     * The number of owners that receive the founding membership tier. The first 100 owners ever
236	     * created are 'FOUNDING'; every owner created thereafter is 'STANDARD'.
237	     */
238	    private static final int FOUNDING_TIER_LIMIT = 100;
239	
240	    /**
241	     * Determines the membership tier for a newly created owner based on its sequential membership
242	     * number. Owners whose membership number is within the first {@value #FOUNDING_TIER_LIMIT} are
243	     * 'FOUNDING'; all later owners are 'STANDARD'.
244	     */
245	    private String determineMembershipTier(int membershipNumber) {
246	        return membershipNumber <= FOUNDING_TIER_LIMIT ? "FOUNDING" : "STANDARD";
247	    }
248	
249	    /**
250	     * Generates the customer code for a newly created owner. The code is formatted as
251	     * '&lt;UPPERCASE_CITY&gt;-&lt;NNNN&gt;' where NNNN is one more than the number of owners that
252	     * already exist in that city, zero-padded to four digits (for example 'LONDON-0007').
253	     * Cities are matched ignoring letter case.
254	     */
255	    private String generateCustomerCode(String city) {
256	        long ownersInCity = this.clinicService.findAllOwners().stream()
257	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
258	            .count();
259	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
260	    }
261	
262	    /**
263	     * Normalizes the city of a newly created owner. If an owner already exists in the same
264	     * city (matched ignoring letter case), that existing owner's exact spelling of the city is
265	     * reused so that all owners in a city share one canonical spelling. Otherwise the supplied
266	     * city is title-cased, capitalizing the first letter of each whitespace-separated word and
267	     * lowercasing the rest, so for example "new york" becomes "New York".
268	     */
269	    private String normalizeCity(String city) {
270	        if (city == null) {
271	            return null;
272	        }
273	        return this.clinicService.findAllOwners().stream()
274	            .map(Owner::getCity)
275	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
276	            .findFirst()
277	            .orElseGet(() -> toTitleCase(city));
278	    }
279	
280	    /**
281	     * Title-cases the given value by capitalizing the first letter of each whitespace-separated
282	     * word and lowercasing the remaining letters, preserving the original whitespace: for example
283	     * "new  YORK" becomes "New  York".
284	     */
285	    private static String toTitleCase(String value) {
286	        StringBuilder result = new StringBuilder(value.length());
287	        boolean capitalizeNext = true;
288	        for (int i = 0; i < value.length(); i++) {
289	            char c = value.charAt(i);
290	            if (Character.isWhitespace(c)) {
291	                capitalizeNext = true;
292	                result.append(c);
293	            } else if (capitalizeNext) {
294	                result.append(Character.toTitleCase(c));
295	                capitalizeNext = false;
296	            } else {
297	                result.append(Character.toLowerCase(c));
298	            }
299	        }
300	        return result.toString();
301	    }
302	
303	    /**
304	     * Determines whether an owner already exists that uses the same telephone number
305	     * as the given one. Telephone numbers must be unique across all owners. The
306	     * comparison ignores letter case and any surrounding or repeated whitespace.
307	     */
308	    private boolean isDuplicateOwner(Owner owner) {
309	        String telephone = normalizeTelephone(owner.getTelephone());
310	        return this.clinicService.findAllOwners().stream()
311	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
312	    }
313	
314	    /**
315	     * Normalizes a telephone number for storage and comparison by stripping spaces, dashes
316	     * and parentheses so that only digits remain: for example "(613) 555-0100" becomes
317	     * "6135550100". This lets differently punctuated forms of the same number be treated as
318	     * equal for the uniqueness check and stored in a single canonical form.
319	     */
320	    private static String normalizeTelephone(String telephone) {
321	        if (telephone == null) {
322	            return null;
323	        }
324	        return telephone.replaceAll("[\\s()-]", "");
325	    }
326	
327	    /**
328	     * Determines whether another owner already uses the same email address as the given one.
329	     * Email addresses, when supplied, must be unique across all owners. An owner without an
330	     * email address is never considered a duplicate. The comparison ignores letter case and
331	     * any surrounding or repeated whitespace.
332	     */
333	    private boolean isDuplicateEmail(Owner owner) {
334	        String email = normalize(owner.getEmail());
335	        if (email == null || email.isEmpty()) {
336	            return false;
337	        }
338	        return this.clinicService.findAllOwners().stream()
339	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
340	    }
341	
342	    /**
343	     * Normalizes a user-supplied value for duplicate detection so that comparisons ignore
344	     * letter case and any surrounding or repeated whitespace: for example "  john   smith "
345	     * and "John Smith" normalize to the same key and so count as the same person.
346	     */
347	    private static String normalize(String value) {
348	        if (value == null) {
349	            return null;
350	        }
351	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
352	    }
353	
354	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
355	    @Override
356	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
357	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
358	        if (currentOwner == null) {
359	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
360	        }
361	        currentOwner.setAddress(ownerFieldsDto.getAddress());
362	        currentOwner.setCity(ownerFieldsDto.getCity());
363	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
364	        currentOwner.setLastName(ownerFieldsDto.getLastName());
365	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
366	        this.clinicService.saveOwner(currentOwner);
367	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
368	    }
369	
370	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
371	    @Transactional
372	    @Override
373	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
374	        Owner owner = this.clinicService.findOwnerById(ownerId);
375	        if (owner == null) {
376	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
377	        }
378	        this.clinicService.deleteOwner(owner);
379	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
380	    }
381	
382	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
383	    @Override
384	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
385	        Owner owner = this.clinicService.findOwnerById(ownerId);
386	        if (owner == null) {
387	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
388	        }
389	        HttpHeaders headers = new HttpHeaders();
390	        Pet pet = petMapper.toPet(petFieldsDto);
391	        owner.setId(ownerId);
392	        pet.setOwner(owner);
393	        pet.getType().setName(null);
394	        this.clinicService.savePet(pet);
395	        PetDto petDto = petMapper.toPetDto(pet);
396	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
397	            .buildAndExpand(pet.getId()).toUri());
398	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
399	    }
400	
401	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
402	    @Override
403	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
404	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
405	        if (currentOwner != null) {
406	            Pet currentPet = this.clinicService.findPetById(petId);
407	            if (currentPet != null) {
408	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
409	                currentPet.setName(petFieldsDto.getName());
410	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
411	                this.clinicService.savePet(currentPet);
412	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
413	            }
414	        }
415	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
416	    }
417	
418	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
419	    @Override
420	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
421	        HttpHeaders headers = new HttpHeaders();
422	        Visit visit = visitMapper.toVisit(visitFieldsDto);
423	        Pet pet = new Pet();
424	        pet.setId(petId);
425	        visit.setPet(pet);
426	        this.clinicService.saveVisit(visit);
427	        VisitDto visitDto = visitMapper.toVisitDto(visit);
428	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
429	            .buildAndExpand(visit.getId()).toUri());
430	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
431	    }
432	
433	
434	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
435	    @Override
436	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
437	        Owner owner = this.clinicService.findOwnerById(ownerId);
438	        if (owner != null) {
439	            Pet pet = owner.getPet(petId);
440	            if (pet != null) {
441	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
442	            }
443	        }
444	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
445	    }
446	}
